  const rIntSpace3 = parseIfMatch(`"${validSampleHash.slice(0, 63)} "`);
  testAssert(rIntSpace3.status === 'invalid' && rIntSpace3.valid === false, 'Internal whitespace: space before closing quote is rejected');

