    testAssert(statuses[0] === 200 && statuses[1] === 412, 'Scenario 17 (Concurrent PUT): One request returns 200, the other returns 412');
    const winnerRes = cRes1.status === 200 ? cRes1 : cRes2;
    currentETag = winnerRes.headers.get('etag');

