    function sendRawHttpGet(rawPath, headers = {}) {
      return new Promise((resolve, reject) => {
        const req = http.request(
          {
            hostname: HOST,
            port: PORT,
            path: rawPath,
            method: 'GET',
            headers: {
              Host: EXPECTED_HOST,
              ...headers,
            },
          },
          (res) => {
            const chunks = [];
            res.on('data', (c) => chunks.push(c));
            res.on('end', () => {
              resolve({
                status: res.statusCode,
                headers: res.headers,
                text: Buffer.concat(chunks).toString('utf8'),
              });
            });
          }
        );
        req.on('error', reject);
        req.end();
      });
    }

